// vendor-map.mjs - inline MapLibre GL JS + the pmtiles reader into src/map/vendor.generated.ts, so the
// map page loads nothing from the network (no CDN, no tile server). Run by the build; output is git-ignored.
import fs from "node:fs";
const nm = new URL("../node_modules/", import.meta.url);
const read = (p) => fs.readFileSync(new URL(p, nm), "utf8");
const out = new URL("../src/map/vendor.generated.ts", import.meta.url);
fs.writeFileSync(out,
  "// GENERATED by scripts/vendor-map.mjs - do not edit\n" +
  "export const MAPLIBRE_JS = " + JSON.stringify(read("maplibre-gl/dist/maplibre-gl.js")) + ";\n" +
  "export const MAPLIBRE_CSS = " + JSON.stringify(read("maplibre-gl/dist/maplibre-gl.css")) + ";\n" +
  "export const PMTILES_JS = " + JSON.stringify(read("pmtiles/dist/pmtiles.js")) + ";\n");
console.log("vendored map libraries ->", out.pathname, fs.statSync(out).size, "bytes");
